    /// Point at a variable array's elements, rejecting any range that would
    /// run past the end of the file.  Returns false on an out-of-range
    /// descriptor; an absent one is not an error and yields zero elements.
    template <class T>
    bool locate(i32 offset, i32 size, size_t& count, const T*& first) const {
        count = 0;
        first = nullptr;
        if (offset <= 0 || size <= 0) return true;
        const auto off = static_cast<size_t>(offset);
        const auto len = static_cast<size_t>(size);
        if (off > payload.size() || len > payload.size() - off) return false;
        count = len / sizeof(T);
        first = reinterpret_cast<const T*>(payload.data() + off);
        return true;
    }

    /// Map the struct image, validating magic and length.
    template <class T>
    const T* image() const {
        if (file.size() < kHeaderSize + sizeof(T)) return nullptr;
        u32 magic = 0;
        std::memcpy(&magic, file.data(), sizeof(magic));
        if (magic != kSnoMagic) return nullptr;
        return reinterpret_cast<const T*>(file.data() + kHeaderSize);
    }

